<script setup lang="ts">
import type { Actor, Unit, Page, Station } from '~/utils/types'
const { actor, admin, unitAdmin } = useSession(); const api = useApi()
const users = ref<Actor[]>([]); const units = ref<Unit[]>([]); const stations = ref<Station[]>([]); const cursor = ref<string | null>(); const error = ref<unknown>(); const message = ref(''); const loading = ref(false); const saving = ref(false); const selected = ref<Actor | null>(null)
const form = reactive({ email: '', display_name: '', unit_id: '', unit_role: 'STAFF', is_active: true, reason: '' })
const grantUser = ref<Actor | null>(null); const grantStations = ref<string[]>([]); const grantCourier = ref(false); const grantReason = ref('')
const administeredUnits = computed(() => actor.value?.memberships.filter(m => m.is_active && m.role === 'UNIT_ADMIN').map(m => m.unit_id) || [])
const managedUnit = ref(administeredUnits.value[0] || '')
const availableUnits = computed(() => admin.value ? units.value : units.value.filter(u => administeredUnits.value.includes(u.id)))
async function load(more=false) { if (!admin.value && !unitAdmin.value) return; loading.value = true; error.value = undefined; try { const page = await api.get<Page<Actor>>(`/users?limit=100${!admin.value ? `&unit_id=${encodeURIComponent(managedUnit.value)}` : ''}${more && cursor.value ? `&cursor=${encodeURIComponent(cursor.value)}` : ''}`); users.value = more ? [...users.value, ...page.items] : page.items; cursor.value = page.next_cursor; units.value = (await api.get<Page<Unit>>('/units?limit=100')).items; if (admin.value) stations.value = (await api.get<Page<Station>>('/stations')).items; if (!form.unit_id) form.unit_id = availableUnits.value[0]?.id || '' } catch(e) { error.value=e } finally { loading.value=false } }
function edit(user?: Actor) { selected.value=user || null; const membership = user?.memberships.find(m => admin.value || administeredUnits.value.includes(m.unit_id)); Object.assign(form,{ email:user?.email || '', display_name:user?.display_name || '', unit_id:membership?.unit_id || availableUnits.value[0]?.id || '', unit_role:membership?.role || 'STAFF', is_active:user?.is_active ?? true, reason:'' }); message.value='' }
async function save() { saving.value=true; error.value=undefined; message.value=''; try { if (selected.value) await api.command(`/users/${selected.value.id}`, { display_name:form.display_name.trim(), unit_id:form.unit_id, unit_role:form.unit_role, is_active:form.is_active, expected_version:selected.value.version, reason:form.reason.trim() }, 'PATCH'); else await api.command('/users', { email:form.email.trim().toLowerCase(), display_name:form.display_name.trim(), unit_id:form.unit_id, unit_role:form.unit_role }); edit(); message.value='บันทึกผู้ใช้แล้ว ผู้ใช้ใหม่ต้องเข้าสู่ระบบด้วย Google ของตน'; await load() } catch(e) { error.value=e } finally { saving.value=false } }
function canEdit(user:Actor) { return !user.system_roles.includes('ADMIN') && (admin.value || user.memberships.some(m => m.role==='STAFF' && administeredUnits.value.includes(m.unit_id))) }
function chooseGrants(user: Actor) { grantUser.value=user; grantStations.value=[...(user.station_ids || [])]; grantCourier.value=user.system_roles.includes('COURIER'); grantReason.value='' }
async function saveGrants() { if (!grantUser.value) return; saving.value=true; error.value=undefined; try { await api.command(`/users/${grantUser.value.id}/grants`,{expected_version:grantUser.value.version, station_ids:grantStations.value, capabilities:[...(grantUser.value.capabilities || []).filter(c => c !== 'COURIER'), ...(grantCourier.value ? ['COURIER'] : [])], reason:grantReason.value.trim()},'PATCH'); grantUser.value=null; message.value='บันทึกสิทธิ์ Station แล้ว'; await load() } catch(e) { error.value=e } finally { saving.value=false } }
onMounted(()=>load())
</script>
<template><div class="page-head"><div><h1>จัดการผู้ใช้หน่วยงาน</h1><p>เพิ่มบัญชี @mfu.ac.th ในรายการอนุญาต บัญชีจะผูก Google เมื่อเข้าสู่ระบบครั้งแรก</p></div></div><Feedback v-if="!admin && !unitAdmin" :error="new Error('บัญชีนี้ไม่มีสิทธิ์จัดการผู้ใช้')" /><template v-else><Feedback :error="error" :message="message" /><div v-if="!admin" class="field"><label for="managed-unit">หน่วยงานที่ดูแล</label><select id="managed-unit" v-model="managedUnit" @change="edit(); load()"><option v-for="unit in availableUnits" :key="unit.id" :value="unit.id">{{ unit.name }}</option></select></div><div class="split"><section class="panel"><div class="page-head"><h2>ผู้ใช้ที่คุณจัดการได้</h2><button type="button" class="text-link" @click="load()">โหลดล่าสุด</button></div><UProgress v-if="loading" /><div v-if="!users.length && !loading" class="empty">ยังไม่มีผู้ใช้ในขอบเขตของคุณ</div><div class="table-wrap"><table v-if="users.length"><thead><tr><th>บัญชี</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><p class="row-title">{{ user.display_name }}</p><p class="break">{{ user.email }}</p><small>{{ user.memberships.map(m => m.role).join(', ') }}</small></td><td><StatusTag :value="user.identity_status" /><p class="hint">{{ user.is_active ? 'เปิดใช้งาน' : 'ปิดใช้งาน' }}</p></td><td><button v-if="canEdit(user)" type="button" class="text-link" @click="edit(user)">แก้ไข</button><button v-if="admin && !user.system_roles.includes('ADMIN')" type="button" class="text-link" @click="chooseGrants(user)">สิทธิ์ Station</button></td></tr></tbody></table></div><button v-if="cursor" class="button actions" :disabled="loading" @click="load(true)">โหลดผู้ใช้เพิ่มเติม</button></section><form class="panel" @submit.prevent="save"><h2>{{ selected ? 'แก้ไขผู้ใช้' : 'เพิ่มผู้ใช้' }}</h2><div class="field"><label for="user-email">อีเมล MFU</label><input id="user-email" v-model="form.email" type="email" required pattern="[^@\s]+@mfu\.ac\.th" :disabled="!!selected" placeholder="name@mfu.ac.th" /></div><div class="field"><label for="user-name">ชื่อที่แสดง</label><input id="user-name" v-model="form.display_name" required maxlength="255" /></div><div class="field"><label for="user-unit">หน่วยงาน</label><select id="user-unit" v-model="form.unit_id" required><option disabled value="">เลือกหน่วยงาน</option><option v-for="unit in availableUnits" :key="unit.id" :value="unit.id">{{ unit.name }}</option></select></div><div class="field"><label for="user-role">สิทธิ์หน่วยงาน</label><select id="user-role" v-model="form.unit_role" required><option value="STAFF">STAFF · เจ้าหน้าที่</option><option v-if="admin" value="UNIT_ADMIN">UNIT_ADMIN · ผู้ดูแลหน่วยงาน</option></select></div><template v-if="selected"><label><input v-model="form.is_active" type="checkbox" /> เปิดใช้งานบัญชี</label><div class="field inline-reason"><label for="user-reason">เหตุผลการแก้ไข</label><textarea id="user-reason" v-model="form.reason" required maxlength="1000" /></div></template><p class="hint">ระบบป้องกันการปิดผู้ดูแลคนสุดท้ายและบัญชีที่มีงานค้าง การเปลี่ยนสิทธิ์จะยกเลิกเซสชันที่เกี่ยวข้อง</p><div class="actions"><button class="button primary" :disabled="saving || !form.unit_id">{{ saving ? 'กำลังบันทึก…' : 'บันทึกผู้ใช้' }}</button><button v-if="selected" type="button" class="button" @click="edit()">ยกเลิกแก้ไข</button></div></form></div><form v-if="admin && grantUser" class="panel" @submit.prevent="saveGrants"><h2>สิทธิ์ Station · {{ grantUser.display_name }}</h2><p class="hint">กำหนดจุดที่ Courier เข้าถึงได้อย่างชัดเจน การเป็น STAFF ไม่ให้สิทธิ์ Courier อัตโนมัติ</p><label><input v-model="grantCourier" type="checkbox" /> เปิดสิทธิ์ Courier</label><div v-for="station in stations" :key="station.id"><label><input v-model="grantStations" type="checkbox" :value="station.id" /> {{ station.name }}</label></div><div class="field inline-reason"><label for="grant-reason">เหตุผล</label><input id="grant-reason" v-model="grantReason" required maxlength="1000" /></div><div class="actions"><button class="button primary" :disabled="saving">บันทึกสิทธิ์</button><button type="button" class="button" @click="grantUser=null">ยกเลิก</button></div></form></template></template>
